Here is the commit message:
HADOOP-13699. Configuration does not substitute multiple
 references to the same var.

Here is the root cause:
The bug occurred because the configuration system did not correctly handle cases where multiple references to the same variable were present in a substitution expression. This could lead to incorrect resolutions or infinite loops during variable expansion, particularly when a variable referenced itself. The original implementation lacked robust detection mechanisms for such self-referential and multiple substitution scenarios.

Here is the patch:
    * If var is unbounded the current state of expansion "prefix${var}suffix" is
    * returned.
-   *
-   * If a cycle is detected: replacing var1 requires replacing var2 ... requires
-   * replacing var1, i.e., the cycle is shorter than
-   * {@link Configuration#MAX_SUBST} then the original expr is returned.
+   * <p>
+   * This function also detects self-referential substitutions, i.e.
+   * <pre>
+   *   {@code
+   *   foo.bar = ${foo.bar}
+   *   }
+   * </pre>
+   * If a cycle is detected then the original expr is returned. Loops
+   * involving multiple substitutions are not detected.
    *
    * @param expr the literal value of a config key
    */
   private String substituteVars(String expr) {
     if (expr == null) {
       return null;
     }
     String eval = expr;
-    Set<String> evalSet = null;
     for(int s = 0; s < MAX_SUBST; s++) {
       final int[] varBounds = findSubVariable(eval);
       if (varBounds[SUB_START_IDX] == -1) {
         return eval;
       }
       final String var = eval.substring(varBounds[SUB_START_IDX],
           varBounds[SUB_END_IDX]);
       String val = null;
       try {
         if (var.startsWith("env.") && 4 < var.length()) {
           String v = var.substring(4);
           int i = 0;
           for (; i < v.length(); i++) {
             char c = v.charAt(i);
             if (c == ':' && i < v.length() - 1 && v.charAt(i + 1) == '-') {
               val = getenv(v.substring(0, i));
               if (val == null || val.length() == 0) {
                 val = v.substring(i + 2);
               }
               break;
             } else if (c == '-') {
               val = getenv(v.substring(0, i));
               if (val == null) {
                 val = v.substring(i + 1);
               }
               break;
             }
           }
           if (i == v.length()) {
             val = getenv(v);
           }
         } else {
           val = getProperty(var);
         }
       } catch(SecurityException se) {
         LOG.warn("Unexpected SecurityException in Configuration", se);
       }
       if (val == null) {
         val = getRaw(var);
       }
       if (val == null) {
         return eval; // return literal ${var}: var is unbound
       }

